// ============================================================
// DETERMINISTIC CORE — there is NO AI in this node.
//   1) Parse the AI's JSON (with fallback if it isn't valid JSON)
//   2) RE-COMPUTE every total ourselves (never trust an LLM for arithmetic)
//   3) Rule checks: required fields, currency allowlist, vendor allowlist
//   4) Decide the route: AUTO_APPROVED | NEEDS_APPROVAL | REJECT_TO_MANUAL
// ============================================================
const cfg = $('⚙️ Config (thresholds & allowlists)').first().json.config;

// LLM output field name varies by node/version — accept the common ones.
const raw =
  $json.text ?? $json.output ?? $json.response ??
  (typeof $json.message === 'object' ? $json.message.content : $json.message) ??
  $json.content ?? '';

// ---- Fallback handling: AI did not return parseable JSON ----
function tryParse(s) {
  if (s && typeof s === 'object') return s;
  let t = String(s).trim();
  t = t.replace(/^\x60{3}(json)?/i, '').replace(/\x60{3}$/, '').trim(); // strip markdown code fences
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a !== -1 && b !== -1) t = t.slice(a, b + 1);
  return JSON.parse(t);
}

let inv, parseError = null;
try {
  inv = tryParse(raw);
} catch (e) {
  parseError = 'AI_OUTPUT_UNPARSEABLE: ' + e.message;
  inv = { vendor_name:'', invoice_number:'', invoice_date:'', currency:'',
          line_items:[], subtotal:0, tax:0, stated_total:0, extraction_confidence:0 };
}

const num = (n) => (Number(n) || 0);
const round2 = (n) => Math.round(num(n) * 100) / 100;

// ---- Re-compute the maths deterministically ----
const lineItems = Array.isArray(inv.line_items) ? inv.line_items : [];
const computedLineSum = round2(lineItems.reduce((s, li) => s + num(li.amount), 0));
const subtotal        = round2(inv.subtotal);
const tax             = round2(inv.tax);
const computedTotal   = round2(subtotal + tax);
const statedTotal     = round2(inv.stated_total);
const tol             = num(cfg.totalTolerance) || 0.05;

const lineItemsMatchSubtotal = Math.abs(computedLineSum - subtotal) <= tol;
const totalMatches           = Math.abs(computedTotal - statedTotal) <= tol;
const mathOk                 = lineItemsMatchSubtotal && totalMatches;

// ---- Rule-based checks ----
const requiredMissing = [];
if (!inv.vendor_name)    requiredMissing.push('vendor_name');
if (!inv.invoice_number) requiredMissing.push('invoice_number');
if (!statedTotal)        requiredMissing.push('stated_total');

const allowedCur = (cfg.allowedCurrencies || []).map(c => String(c).toUpperCase());
const currencyOk = allowedCur.includes(String(inv.currency || '').toUpperCase());

const approved   = (cfg.approvedVendors || []).map(v => String(v).toUpperCase());
const vendorKnown = approved.includes(String(inv.vendor_name || '').toUpperCase());

const confFloor    = num(cfg.confidenceFloor) || 0.6;
const lowConfidence = num(inv.extraction_confidence) < confFloor;

const threshold = num(cfg.approvalThresholdUSD) || 5000;

// ---- Decision logic (deterministic thresholds + routing) ----
const reasons = [];
let decision, routeIndex;

if (parseError || requiredMissing.length || !mathOk || !currencyOk || lowConfidence) {
  decision = 'REJECT_TO_MANUAL'; routeIndex = 2;
  if (parseError)            reasons.push(parseError);
  if (requiredMissing.length) reasons.push('Missing required fields: ' + requiredMissing.join(', '));
  if (!mathOk)               reasons.push('Math check failed: line items=' + computedLineSum +
                                          ', subtotal=' + subtotal + ', computed total=' + computedTotal +
                                          ', stated total=' + statedTotal);
  if (!currencyOk)           reasons.push('Currency not allowed: ' + (inv.currency || '(none)'));
  if (lowConfidence)         reasons.push('Low extraction confidence: ' + num(inv.extraction_confidence));
} else if (!vendorKnown || statedTotal >= threshold) {
  decision = 'NEEDS_APPROVAL'; routeIndex = 1;
  if (!vendorKnown)            reasons.push('Vendor not on approved list: ' + inv.vendor_name);
  if (statedTotal >= threshold) reasons.push('Amount ' + statedTotal + ' >= approval threshold ' + threshold);
} else {
  decision = 'AUTO_APPROVED'; routeIndex = 0;
  reasons.push('Passed all checks and below approval threshold (' + threshold + ')');
}

return [{
  json: {
    decision, routeIndex, reasons,
    validation: {
      mathOk, lineItemsMatchSubtotal, totalMatches,
      computedLineSum, subtotal, tax, computedTotal, statedTotal,
      currencyOk, vendorKnown, lowConfidence, requiredMissing, parseError
    },
    invoice: inv,
    meta: {
      source:      $('📄 Sample Invoice (OCR text)').first().json.source,
      sampleIndex: $('📄 Sample Invoice (OCR text)').first().json.sampleIndex,
      receivedAt:  $('📄 Sample Invoice (OCR text)').first().json.receivedAt,
      processedAt: '2026-06-04T00:00:00.000Z'
    }
  }
}];

