// If the "Human Approval (Email)" node is ENABLED, its output carries the
// approver's choice. When it is DISABLED (demo default), data passes straight
// through with no approval field -> we record the row as PENDING.
const v = $('🧮 Validate & Decide (deterministic)').first().json;

// The send-&-wait approval output shape varies by n8n version; check the
// common spots. (Node is disabled by default -> none present -> PENDING.)
const d = ($json && typeof $json === 'object') ? $json : {};
let approved;
if (d.approved === true  || (d.data && d.data.approved === true))  approved = true;
else if (d.approved === false || (d.data && d.data.approved === false)) approved = false;
else approved = undefined;

let status, approver;
if (approved === true)       { status = 'APPROVED_BY_HUMAN'; approver = 'human-reviewer'; }
else if (approved === false) { status = 'REJECTED_BY_HUMAN'; approver = 'human-reviewer'; }
else                         { status = 'PENDING_HUMAN_APPROVAL'; approver = 'unassigned'; }

return [{
  json: {
    processed_at:   v.meta.processedAt,
    status,
    decision:       v.decision,
    vendor:         v.invoice.vendor_name,
    invoice_number: v.invoice.invoice_number,
    invoice_date:   v.invoice.invoice_date,
    currency:       v.invoice.currency,
    amount:         v.validation.statedTotal,
    vendor_known:   v.validation.vendorKnown,
    math_ok:        v.validation.mathOk,
    reasons:        v.reasons.join(' | '),
    approver,
    ai_note:        $('🤖 AI #2: Risk Review (for approver)').first().json.text
                      ?? $('🤖 AI #2: Risk Review (for approver)').first().json.output ?? ''
  }
}];
